import { sql } from "drizzle-orm";
import {
  boolean,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

import { DISH_SOURCE_TYPES } from "@/lib/recipes/draft";

import { users } from "./auth-schema";

/**
 * Better Auth tables (`users`, `sessions`, `accounts`, `verifications`) are
 * generated by the Better Auth CLI into `./auth-schema.ts` and re-exported
 * here so drizzle-kit — pointed at this file by `drizzle.config.ts` — picks
 * them up in the regular migration pipeline (VISION §6.7). Never hand-edit
 * `auth-schema.ts`; regenerate it (see `better-auth.config.ts`) instead.
 */
export * from "./auth-schema";

/**
 * A household — the top-level tenant every other entity belongs to (VISION
 * §5). MVP: a user belongs to a single household.
 */
export const households = pgTable("households", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * Membership of a user in a household — the row every household-scoped
 * request is authorized against (VISION §6.7, `householdProcedure`).
 *
 * The unique index on `user_id` is the MVP invariant "one household per
 * user" (VISION §5) expressed in the database rather than in application
 * code, so a concurrent create/accept race ends in a constraint violation
 * instead of a second membership. Application code maps that violation to a
 * CONFLICT; it must never work around it.
 */
export const householdMembers = pgTable(
  "household_members",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    joinedAt: timestamp("joined_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    uniqueIndex("household_members_userId_uidx").on(table.userId),
    index("household_members_householdId_idx").on(table.householdId),
  ],
);

/**
 * A one-time invite link with a TTL (VISION §5, §6.7).
 *
 * The row is the whole security model: `token` is the unguessable secret,
 * `expires_at` the TTL, and `used_at`/`used_by` the one-time stamp. Accepting
 * claims the invite with `UPDATE ... WHERE used_at IS NULL`, so two people
 * opening the same link race on the database rather than on a read.
 *
 * Both user references cascade rather than blocking a user deletion:
 * `created_by` takes the invite with it, `used_by` merely forgets who
 * redeemed it (the membership row is the record that matters).
 */
export const invites = pgTable(
  "invites",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    token: text("token").notNull().unique(),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    usedAt: timestamp("used_at", { withTimezone: true }),
    usedBy: text("used_by").references(() => users.id, {
      onDelete: "set null",
    }),
  },
  (table) => [index("invites_householdId_idx").on(table.householdId)],
);

/**
 * A store department a household's product catalog is grouped by (VISION
 * §3.1, §5), e.g. "Овощи и фрукты". Seeded with 7 defaults for every new
 * household (`src/server/catalog/default-categories.ts`, hooked into
 * `household.create`); `sortOrder` is user-editable per household so the
 * list can be reordered to match a real store's walking route
 * (`category.reorder`, task 7.1 for the drag UI).
 */
export const categories = pgTable(
  "categories",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    icon: text("icon").notNull(),
    sortOrder: integer("sort_order").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    uniqueIndex("categories_householdId_name_uidx").on(
      table.householdId,
      table.name,
    ),
    index("categories_householdId_sortOrder_idx").on(
      table.householdId,
      table.sortOrder,
    ),
  ],
);

/**
 * A product in a household's own catalog (VISION §3.1, §5) — the thing a cart
 * item, a pantry item and a recipe ingredient all point at.
 *
 * Adding to the cart goes exclusively through autocomplete over this table
 * (task 1.3), which is what makes "помидоры и вверху, и внизу" impossible by
 * construction: a name resolves to one row, and the cart's own partial unique
 * index (task 2.1) then allows one active item per row.
 *
 * Uniqueness is on `normalizedName` — a stored, canonical form of `name`
 * written by every insert and every rename — rather than on an expression
 * over `name`. The point is that the database enforces **the application's
 * own** definition of "the same product" (`normalizeProductName`: lower-case,
 * ё→е, collapsed whitespace), not a weaker approximation of it. A `lower(name)`
 * index would happily admit «Сёмга» and «Семга» as two rows, which the
 * autocomplete treats as one product — the duplicate this whole feature
 * exists to prevent, minted permanently and only reachable through an edit.
 *
 * The column is redundant with `name` by construction, and that is the trade:
 * a canonical value can be indexed and compared exactly, while a normalization
 * this specific cannot be expressed as an index expression Postgres would
 * still use for lookups. Writes go through `product.create`/`product.update`,
 * which set the two together; nothing else may write `name` alone.
 *
 * `categoryId` is `restrict`, not `cascade`: a department that still groups
 * products must not be deletable out from under them (there is no delete
 * endpoint yet — this is the guard for when task 7.1 adds one).
 * `createdBy` is `set null` because the catalog belongs to the household, not
 * to whoever typed the name first.
 */
export const products = pgTable(
  "products",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    categoryId: uuid("category_id")
      .notNull()
      .references(() => categories.id, { onDelete: "restrict" }),
    name: text("name").notNull(),
    /**
     * `normalizeProductName(name)` — the canonical form uniqueness is on.
     * Always written together with `name`; never edited on its own.
     */
    normalizedName: text("normalized_name").notNull(),
    /** A single emoji — picked from the reference catalog or by the AI. */
    icon: text("icon").notNull(),
    /** One of `UNITS` (`src/lib/units.ts`), stored as text. */
    defaultUnit: text("default_unit").notNull(),
    /** Lowercase search aliases: "помидор" also finds "Помидоры". */
    aliases: text("aliases")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    createdBy: text("created_by").references(() => users.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    uniqueIndex("products_householdId_normalizedName_uidx").on(
      table.householdId,
      table.normalizedName,
    ),
    index("products_householdId_categoryId_idx").on(
      table.householdId,
      table.categoryId,
    ),
  ],
);

/**
 * One closed shopping run (VISION §3.1, §5) — what «Завершить закупку»
 * creates.
 *
 * There is no "open trip" row and no `openedAt`: a trip only ever comes into
 * existence at the moment it is closed, when `trip.close` (task 3.2) stamps
 * its id onto every `bought` cart item in one transaction. Until then the
 * household simply has active cart items, and "the current trip" is the set of
 * rows with `trip_id IS NULL` — which is precisely what the cart's partial
 * unique index is built on. Modelling an open trip as a row would mean a
 * second source of truth for the same fact, and a household could then have
 * zero or two of them.
 *
 * The table was created ahead of that endpoint, from the very first
 * migration, so `cart_items.trip_id` has a foreign key target — the invariant
 * below is unexpressible without one.
 */
export const shoppingTrips = pgTable(
  "shopping_trips",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    closedAt: timestamp("closed_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    index("shopping_trips_householdId_closedAt_idx").on(
      table.householdId,
      table.closedAt,
    ),
  ],
);

/**
 * `нужно` → `заказано` → `куплено` (VISION §3.1). `ordered` is the delivery
 * state (Wolt Market, Carrefour): the other partner sees there is nothing left
 * to buy in a shop. It is a station on the way to `bought`, not a terminal
 * state — «Заказ получен» moves the group on.
 */
export const cartItemStatusEnum = pgEnum("cart_item_status", [
  "needed",
  "ordered",
  "bought",
]);

/**
 * A line in the household's shared shopping list (VISION §3.1, §5).
 *
 * **The invariant this table exists for: one active row per product.** It is
 * the partial unique index `(product_id) WHERE trip_id IS NULL` — active means
 * "not yet carried off by a closed trip", so a product may appear once in the
 * live cart and any number of times across purchase history. The index needs
 * no `household_id`: a product row belongs to exactly one household, so
 * uniqueness per product is already at least as strict as uniqueness per
 * (household, product) — never weaker.
 *
 * That is a statement about `products`, not about this table's own foreign
 * keys, which are independent and therefore do **not** by themselves force
 * `cart_items.household_id` to equal `products.household_id`. Keeping the two
 * in step is the router's job: `cart.add` checks the client's `productId`
 * against the caller's own catalog before it inserts, exactly as
 * `product.update` checks a `categoryId` against the caller's own departments
 * (the same shape of guard, for the same reason).
 *
 * The index is the authority, not a pre-check: adding a product that is
 * already in the cart raises the existing row's quantity instead of minting a
 * second one (`src/server/cart/merge.ts`), and two partners adding «помидоры»
 * at the same instant race in Postgres rather than on a read. «Помидоры и
 * вверху, и внизу» — the note-app pain this whole product started from — is
 * impossible by construction, not by convention. Application code must never
 * work around this index (AGENTS.md).
 *
 * `product_id` is `restrict`, unlike the household-cascading columns around
 * it: purchase history that still points at a product must not lose what was
 * actually bought. Both user references are `set null` — the cart belongs to
 * the household, not to whoever typed the line, and a departing member must
 * not take the shopping list with them.
 *
 * `trip_id` deliberately has no cascade in either direction: deleting a trip
 * is not a thing the app does, and if it ever were, silently deleting the
 * purchase records that name it is the last thing anyone would want.
 *
 * `qty` is `numeric(10, 3)` in `number` mode — «0.5 кг» has to survive a round
 * trip, which rules out an integer column, and a float would make «0.1 + 0.2»
 * a support ticket. Three decimals is the resolution groceries are actually
 * bought at; the range (up to 9 999 999.999) stays far inside what a double
 * represents exactly, so the mode is lossless here.
 *
 * `unit` and `ordered_via` are `text`, not enums: both are re-validated on
 * read (`unitSchema`, `orderedViaSchema`) the same way `products.default_unit`
 * is, and neither wants a migration every time the list grows. `status` *is* a
 * real enum — it drives every branch of the merge rules, and an unknown value
 * there would have no safe fallback.
 */
export const cartItems = pgTable(
  "cart_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "restrict" }),
    qty: numeric("qty", { precision: 10, scale: 3, mode: "number" }).notNull(),
    /** One of `UNITS` (`src/lib/units.ts`), stored as text. */
    unit: text("unit").notNull(),
    status: cartItemStatusEnum("status").notNull().default("needed"),
    /** Free-form, e.g. «покрупнее» (VISION §3.1). */
    note: text("note"),
    addedBy: text("added_by").references(() => users.id, {
      onDelete: "set null",
    }),
    /** Who is taking it — «у нас закупки разделены» (VISION §3.1). */
    buyerId: text("buyer_id").references(() => users.id, {
      onDelete: "set null",
    }),
    /** `wolt` / `carrefour` / `other`, meaningful only while `ordered`. */
    orderedVia: text("ordered_via"),
    /** Null while the item is active; stamped by «Завершить закупку». */
    tripId: uuid("trip_id").references(() => shoppingTrips.id),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    uniqueIndex("cart_items_productId_active_uidx")
      .on(table.productId)
      .where(sql`trip_id is null`),
    index("cart_items_householdId_tripId_idx").on(
      table.householdId,
      table.tripId,
    ),
    index("cart_items_tripId_idx").on(table.tripId),
  ],
);

/**
 * "What's at home" (VISION §3.2, §5) — presence only, no quantities, no
 * expiry dates. A deliberate scope cut: full stock-level tracking demands
 * upkeep discipline, and VISION's own reasoning is that such systems get
 * abandoned. A row's mere existence is the entire fact this table records.
 *
 * Populated by «Завершить закупку» (`trip.close`, task 3.2) moving bought cart
 * lines here — an upsert, so buying something already at home refreshes the
 * row rather than failing on the unique index below; emptied one row at a time
 * by «Кончилось» (`pantry.ranOut`), which deletes the row and sends the
 * product back to the cart. There is no update endpoint — a pantry fact is
 * either present or it is gone, never edited.
 *
 * `productId` is `restrict`, the same reasoning as `cart_items.product_id`
 * (VISION §3.1): a pantry fact that still names a product must not survive
 * that product's deletion silently pointing at nothing.
 *
 * **The unique index is on `productId` alone, no `householdId`** — exactly
 * the reasoning `cart_items`' partial unique index documents: a product row
 * belongs to exactly one household, so uniqueness per product is already at
 * least as strict as uniqueness per (household, product), never weaker. One
 * pantry row per product is the whole invariant here: «дома есть» either
 * holds for a product or it doesn't, so a second row for the same product
 * would only be a duplicate of the same fact, not a second fact worth
 * keeping. Unlike `cart_items`' index, this one is not partial — a pantry row
 * has no `tripId`-style "still active" qualifier to scope it by.
 */
export const pantryItems = pgTable(
  "pantry_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id, { onDelete: "restrict" }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    uniqueIndex("pantry_items_productId_uidx").on(table.productId),
    index("pantry_items_householdId_idx").on(table.householdId),
  ],
);

/**
 * A household's kitchen equipment and headcount (VISION §3.3, §5): the
 * "kitchen profile" a recipe is checked against and the assistant reads for
 * "adapt this to what we have". Set from S2 onboarding (skippable) and
 * editable from S12 settings (task 1.4).
 *
 * `householdId` is the primary key rather than a separate `id` — the row is
 * 1:1 with its household by construction, so there is nothing a second key
 * would ever address that the household id doesn't already. `equipment`
 * stores a mix of preset slugs (`src/server/kitchen/equipment.ts`) and
 * free-form strings side by side, matching VISION §5 "checklist + free-form
 * entry": the presets are just the entries the UI renders as checkboxes
 * instead of chips.
 */
export const kitchenProfiles = pgTable("kitchen_profiles", {
  householdId: uuid("household_id")
    .primaryKey()
    .references(() => households.id, { onDelete: "cascade" }),
  householdSize: integer("household_size").notNull().default(2),
  equipment: text("equipment")
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * `adapt_recipe` is **appended**, never inserted: drizzle-kit then emits a
 * plain `ALTER TYPE … ADD VALUE` rather than an `ADD VALUE … BEFORE` or a
 * type recreate, and only the plain form is backward-compatible with code
 * already running. It ships in task 4.1 though task 4.6 is the first to write
 * it, because `migrate.yml` and the Vercel deploy of the same commit run in
 * **parallel** — shipping the value several PRs early removes the window
 * where the function could go live before the type knows the word. The rule
 * that follows from the same fact: never write or select a new enum value in
 * the migration batch that adds it.
 */
export const aiJobTypeEnum = pgEnum("ai_job_type", [
  "product_enrich",
  "parse_photo",
  "parse_url",
  "parse_text",
  "assistant",
  "adapt_recipe",
]);

export const aiJobStatusEnum = pgEnum("ai_job_status", [
  "pending",
  "running",
  "done",
  "error",
]);

/**
 * One OpenAI call, recorded (VISION §5, §6.5).
 *
 * Two jobs at once: the progress a screen renders while an import runs, and
 * the spend ledger. `costUsd` is written for **every** call from the very
 * first AI feature — including calls that failed validation after the HTTP
 * request succeeded, because those were billed too. A cap that only counts
 * the successes under-reports exactly when things go wrong.
 *
 * The `(user_id, created_at)` index backs the rate limiter
 * (`src/server/ai/rate-limit.ts`), which counts a user's recent rows instead
 * of keeping state in memory — the only design that survives serverless, where
 * every request may land in a different instance. `(household_id, created_at)`
 * is for the monthly budget check the assistant adds in task 6.1.
 *
 * `numeric(10, 6)`: a single call costs fractions of a cent, so six decimals
 * is the resolution that keeps a $0.0002 icon lookup from rounding to zero.
 */
export const aiJobs = pgTable(
  "ai_jobs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: aiJobTypeEnum("type").notNull(),
    status: aiJobStatusEnum("status").notNull(),
    /** What the call was about — a product name, a URL, an upload key. */
    inputRef: text("input_ref"),
    outputJson: jsonb("output_json"),
    error: text("error"),
    costUsd: numeric("cost_usd", { precision: 10, scale: 6 })
      .notNull()
      .default("0"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
  },
  (table) => [
    index("ai_jobs_userId_createdAt_idx").on(table.userId, table.createdAt),
    index("ai_jobs_householdId_createdAt_idx").on(
      table.householdId,
      table.createdAt,
    ),
  ],
);

/**
 * Where a dish came from (VISION §3.3): a photo/screenshot, a page, pasted
 * text, or typed by hand.
 *
 * A real enum, unlike `cart_items.unit` / `ordered_via` (deliberately `text`):
 * this is a closed four-value set that drives real branches — S7's «~30 мин ·
 * 📷 с фото» source line and which re-import affordance S8.2 offers — and an
 * unknown value would have no safe fallback. It cannot grow without a code
 * change anyway.
 *
 * The members come from `DISH_SOURCE_TYPES` (`src/lib/recipes/draft.ts`)
 * rather than being spelled out here, for the reason `src/lib/units.ts`
 * documents for `UNITS`: the vocabulary is shared with the client, and only
 * one of the two modules may be imported from a browser bundle.
 */
export const dishSourceTypeEnum = pgEnum("dish_source_type", DISH_SOURCE_TYPES);

/**
 * A dish in the household's library (VISION §3.3, DESIGN_BRIEF S6/S7) — the
 * thing a week's menu names (phase 5) and the assistant looks up (phase 6).
 *
 * A dish and its recipe are one aggregate split over four tables, and
 * `version` is what makes that split safe: **every** write to the dish, its
 * recipe, its ingredients or its steps bumps it by one, and `dish.update`
 * refuses a save whose `expectedVersion` no longer matches. An integer rather
 * than `updated_at`, and that is not a style choice: every router here writes
 * `updatedAt: sql\`now()\`` at microsecond precision, postgres.js parses
 * `timestamptz` down to a millisecond `Date`, and superjson round-trips that
 * — so a `WHERE updated_at = $clientDate` guard could silently never match
 * and turn every legitimate save into a conflict. An integer compares
 * exactly, and doubles as the non-`Date` remount key (`${id}:${version}`)
 * that keeps a background refetch from wiping a half-typed recipe.
 *
 * **Archived, never deleted** (`archived_at`, and no `dish.delete`). Phase
 * 5.1's `menu_items.dish_id` and 5.3's «повторить неделю» must not lose the
 * dish a stored week names; a hard delete would either cascade that history
 * away or start throwing 23503 at the user.
 *
 * **`normalized_title` is deliberately not unique** — the asymmetry with
 * `products.normalized_name` is the point. A duplicate *product* is the bug
 * the catalog exists to prevent; a second «Оладьи» (mum's and the other one)
 * is a library decision the household is allowed to make. The column exists
 * for lookup — the assistant's dish resolution in task 6.1 — not for a
 * constraint.
 *
 * `created_at DESC` is the library order: S6 is a grid you keep importing
 * into, so the dish just added belongs top-left; `id` is the tiebreak that
 * keeps the order stable when two land in the same millisecond.
 *
 * **No GIN index on `tags`** — tag filtering runs client-side over tens of
 * rows (`filterDishes`); the index is additive if server-side filtering ever
 * appears. **No `import_job_id`** either: `ai_jobs.input_ref` and
 * `output_json` already record the import, and a column with no reader is
 * dead weight.
 *
 * `photo_key` ships here though only task 4.3 writes it — additive-first.
 * Without it an orphaned or replaced UploadThing blob is unreachable forever
 * (`UTApi.deleteFiles` takes keys, not URLs).
 *
 * `created_by` is `set null`, like `products.created_by` and
 * `cart_items.added_by`: the library belongs to the household, not to
 * whoever imported first.
 */
export const dishes = pgTable(
  "dishes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    /**
     * `normalizeDishTitle(title)` (`src/server/dishes/normalize.ts`) — the
     * catalog's own canon, aliased. Written together with `title`, never on
     * its own.
     */
    normalizedTitle: text("normalized_title").notNull(),
    /** UploadThing public URL, or a url import's own page image. */
    photoUrl: text("photo_url"),
    /** UploadThing file key — the only handle that can ever delete the blob. */
    photoKey: text("photo_key"),
    /** Lower-cased, deduped free-form tags: «ужин», «духовка», «быстро». */
    tags: text("tags")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    sourceType: dishSourceTypeEnum("source_type").notNull(),
    sourceUrl: text("source_url"),
    /** Aggregate optimistic-concurrency token; see the note above. */
    version: integer("version").notNull().default(1),
    /** Archive, never delete; see the note above. */
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdBy: text("created_by").references(() => users.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    index("dishes_householdId_createdAt_idx").on(
      table.householdId,
      table.createdAt,
    ),
    index("dishes_householdId_normalizedTitle_idx").on(
      table.householdId,
      table.normalizedTitle,
    ),
  ],
);

/**
 * The recipe half of a dish — 1:1 with it, enforced by `unique(dish_id)`.
 *
 * **Its own `id` primary key, not `PRIMARY KEY (dish_id)`.** Children carry
 * `recipe_id`, and a child column named `dish_id` whose foreign key actually
 * points at *this* table would be a trap for every hand-written join and for
 * phase 5. `recipes_dishId_uidx` is where the 1:1 invariant lives, so that no
 * writer can ever give one dish two recipes.
 *
 * It is **not** a guard against a double-tapped «Сохранить блюдо»: that path
 * mints a fresh `dishes.id` first and inserts the recipe against it, so the
 * index cannot fire and the second tap simply produces a second dish. Nothing
 * in the schema deduplicates that — `normalized_title` is deliberately not
 * unique — and the defence is the form's own synchronous ref lock (task 4.2).
 *
 * `ON DELETE cascade` from `dishes`, unlike the `restrict` used elsewhere: a
 * recipe has no meaning apart from its dish. Because dishes archive rather
 * than delete, that cascade is a safety net, not a path.
 *
 * **Two portion integers and a yield noun, no stored Russian label.**
 * DESIGN_BRIEF S7 shows «7–8 печений» literally, and a stored label would be
 * a user-visible string living outside next-intl — an AGENTS.md violation.
 * The client composes it from `portions_min`, `portions_base` and
 * `yield_unit` through an ICU message. Same treatment as the step timer
 * below.
 */
export const recipes = pgTable(
  "recipes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    dishId: uuid("dish_id")
      .notNull()
      .references(() => dishes.id, { onDelete: "cascade" }),
    /**
     * Ingredient quantities are stated for this many portions — the number
     * every rescale divides by, and the **upper** end of a stated range
     * («7–8 печений» → 8). Upper, not lower: a source that says «7–8» has
     * weighed its flour for the batch it actually makes.
     */
    portionsBase: integer("portions_base").notNull().default(2),
    /** The lower end of a stated range, else null. Display only. */
    portionsMin: integer("portions_min"),
    /**
     * The source's own yield noun — «печений», «шт». `null` means «порции».
     * Imported data like `raw_text`, never UI copy: it is passed *into* an
     * ICU message as a parameter, so the words around it still come from
     * next-intl.
     */
    yieldUnit: text("yield_unit"),
    totalTimeMin: integer("total_time_min"),
    /**
     * `EQUIPMENT_PRESETS` slugs **only** — a deliberate deviation from
     * `kitchen_profiles.equipment`, which stores slugs and the user's free
     * text side by side. That array is user-authored; this one exists solely
     * to be compared against it (4.5's banner, 4.6's adaptation), and
     * comparing a parser's «миксер» against a profile's `mixer` silently
     * never matches. A recipe needing something not on the list is a signal
     * to extend `EQUIPMENT_PRESETS`, not to store a free word here.
     */
    equipment: text("equipment")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /**
     * The `RecipeDraft` exactly as imported, before any human or AI edit.
     * Written only by an import; null for a manual dish. Powers 4.6's
     * «вернуть как было» and its proposal diff base — without it, a revert
     * after «Применить» is impossible.
     */
    originalDraft: jsonb("original_draft"),
    /** Written only by task 4.6 — renders S7's «переделано под твою духовку». */
    adaptedAt: timestamp("adapted_at", { withTimezone: true }),
    /**
     * A short machine-written summary of what the adaptation changed. It is
     * AI-generated Russian *content*, not UI chrome, so it is data like
     * `raw_text`; the label around it comes from next-intl.
     */
    adaptedNote: text("adapted_note"),
  },
  (table) => [
    uniqueIndex("recipes_dishId_uidx").on(table.dishId),
    index("recipes_householdId_idx").on(table.householdId),
  ],
);

/**
 * One ingredient line (VISION §3.3, DESIGN_BRIEF §5's NYC Cookies list).
 *
 * **The four-way split `raw_text` / `name` / `note` / `is_optional` is the
 * whole design.** `rawText` is the honesty anchor S8.3's «ИИ мог ошибиться»
 * is checked against and what a later re-match diffs from; `name` is the
 * buyable noun the AI extracted («Шоколад» out of «Шоколад крупными кусками
 * — 150 г»), which is the only reason a free deterministic catalog matcher
 * can work at all; `note` is S7's «(холодное)» sub-line and phase 5.2's
 * `cart_items.note`; `is_optional` is what stops 5.2 buying a garnish by
 * default.
 *
 * **`qty` and `unit` are nullable, and that nullability is the honesty
 * rule** (VISION §6.4). Three states, all present in the design's own sample
 * recipe and all rendered differently:
 * `qty=null, needs_review=true` → «Кукурузный крахмал — уточнить» (amber);
 * `qty=null, is_optional=true` → «Biscoff — опционально» (neutral);
 * `qty=null, note='по вкусу'` → «Соль по вкусу» (plain text).
 * `needs_review` is derived server-side by `deriveNeedsReview`
 * (`src/server/recipes/needs-review.ts`) on every save and never sent by the
 * model — a model that forgets to flag cannot produce a silently confident
 * recipe.
 *
 * `qty numeric(10, 3)` in `number` mode is **byte-identical to
 * `cart_items.qty`, on purpose**: phase 5.2 sums ingredient quantities into
 * cart rows, and a different scale would force a rounding decision at the
 * boundary and let MergePreview disagree with the row it writes. One scale,
 * one rounding rule (`roundQty`, `src/server/cart/merge.ts`). The cost —
 * `⅓+⅓+⅓ = 0.999` — is one the cart already lives with.
 *
 * `unit` is `text`, re-validated on read against `RECIPE_UNITS` and degraded
 * to `null` for anything unrecognized, exactly as `cart_items.unit` degrades
 * to «шт»: one bad row must not fail a whole dish's output validation.
 *
 * **`household_id` on a child table** is required by the tenancy rule
 * (VISION §6.7): `DELETE FROM recipe_ingredients WHERE recipe_id = $1` has
 * nowhere else to put the household predicate, and a predicate expressible
 * only through a join is one refactor away from vanishing.
 *
 * **No unique index on `(recipe_id, product_id)`.** «Молоко 200 мл в тесто» +
 * «молоко 50 мл в глазурь» is a real recipe, not a duplicate; the cart's
 * one-active-row invariant does not generalize here, and deduping is 5.2's
 * summing job. **No CHECK constraints** either (`qty > 0`,
 * `sort_order >= 0`) — consistent with `cart_items`, where bounds live in
 * Zod; constraints are reserved for invariants that must survive a race.
 *
 * `product_id` is `ON DELETE restrict`, like `cart_items.product_id` and
 * `pantry_items.product_id`. **Task 7.1's product-delete endpoint must
 * pre-check** `SELECT count(*) FROM recipe_ingredients WHERE product_id = $1
 * AND household_id = $2` and report «используется в N блюдах», or the delete
 * fails with a raw 23503 the user cannot act on.
 * `recipe_ingredients_productId_idx` exists for exactly that query (and for
 * task 6.1's reverse lookup product → dishes).
 */
export const recipeIngredients = pgTable(
  "recipe_ingredients",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    recipeId: uuid("recipe_id")
      .notNull()
      .references(() => recipes.id, { onDelete: "cascade" }),
    /** Null = unbound: nothing in the catalog answers to this name yet. */
    productId: uuid("product_id").references(() => products.id, {
      onDelete: "restrict",
    }),
    rawText: text("raw_text").notNull(),
    name: text("name").notNull(),
    qty: numeric("qty", { precision: 10, scale: 3, mode: "number" }),
    /** One of `RECIPE_UNITS` (`src/lib/units.ts`), stored as text. */
    unit: text("unit"),
    note: text("note"),
    isOptional: boolean("is_optional").notNull().default(false),
    needsReview: boolean("needs_review").notNull().default(false),
    sortOrder: integer("sort_order").notNull(),
  },
  (table) => [
    index("recipe_ingredients_recipeId_sortOrder_idx").on(
      table.recipeId,
      table.sortOrder,
    ),
    index("recipe_ingredients_householdId_idx").on(table.householdId),
    index("recipe_ingredients_productId_idx").on(table.productId),
  ],
);

/**
 * One numbered step (DESIGN_BRIEF S9 — «Духовка 205 °C … таймер 9–11 мин»).
 *
 * **Two timer integers, no stored label**, for the same reason `recipes`
 * keeps two portion integers: «9–11 мин» is in the design's own sample step,
 * and a `timer_label text` column would be a user-visible Russian string
 * outside next-intl. The client composes the label from the two numbers; the
 * countdown runs `timer_sec`, the lower bound — you check the cookies at 9,
 * not at 11.
 *
 * `step_order` rather than `order` because the latter is reserved SQL, and
 * `sort_order` on `recipe_ingredients` already sets the house style.
 *
 * **The index is deliberately not unique.** The save path is a full replace
 * (`dish.update` deletes the children and re-inserts them with fresh
 * `0..n-1` orders), so it never swaps two rows in place — a unique constraint
 * would buy nothing and would fight any future in-place reorder without a
 * `DEFERRABLE` constraint.
 */
export const recipeSteps = pgTable(
  "recipe_steps",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    recipeId: uuid("recipe_id")
      .notNull()
      .references(() => recipes.id, { onDelete: "cascade" }),
    stepOrder: integer("step_order").notNull(),
    text: text("text").notNull(),
    /** Countdown length in seconds — the LOWER bound of a range. */
    timerSec: integer("timer_sec"),
    /** Upper bound, so «9–11 мин» is two numbers and one ICU message. */
    timerMaxSec: integer("timer_max_sec"),
  },
  (table) => [
    index("recipe_steps_recipeId_stepOrder_idx").on(
      table.recipeId,
      table.stepOrder,
    ),
    index("recipe_steps_householdId_idx").on(table.householdId),
  ],
);

/**
 * Who uploaded which UploadThing blob (task 4.3).
 *
 * The ownership record that turns a file key into a **capability only its
 * uploader's household can spend**. `dishImport.fromPhoto` takes a bare key
 * and rebuilds the image URL server-side (`src/server/uploadthing-url.ts`),
 * so nothing a client sends is ever fetched verbatim — but a key is a short,
 * guessable-shaped string, and without this table any signed-in user could
 * hand the parser a key belonging to another household and have OpenAI read
 * that household's screenshot back to them. The row is what makes
 * `WHERE file_key = $1 AND household_id = $2` expressible at all.
 *
 * **Written from the UploadThing `onUploadComplete` callback**, because that
 * is the only place the key is born: the browser talks to UploadThing
 * directly (Vercel's 4.5 MB body limit is why the bytes never cross tRPC), so
 * the app first learns a key exists when UploadThing calls back. The route's
 * `.middleware()` re-checks the session and the household membership before
 * the upload is even authorized — `src/middleware.ts` excludes `/api/**`, so
 * that callback is a second public entry point and needs the same gate
 * `householdProcedure` gives tRPC.
 *
 * `file_key` is the primary key, not a surrogate id: UploadThing already
 * guarantees it unique, and every lookup is by it. `url` is stored rather
 * than recomputed so a future change of the app id (or of UploadThing's URL
 * shape) cannot orphan the photos already attached to dishes.
 *
 * **A row here is not a promise the blob still exists.** `discardPhoto`
 * deletes both together, and an abandoned import leaves both behind — the
 * orphan hygiene VISION's post-MVP sweep is for (R5). Nothing reads this
 * table except the import router's ownership checks.
 */
export const photoUploads = pgTable(
  "photo_uploads",
  {
    /** The UploadThing file key — the only handle that can delete the blob. */
    fileKey: text("file_key").primaryKey(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    /** The public URL as UploadThing served it at upload time. */
    url: text("url").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [index("photo_uploads_householdId_idx").on(table.householdId)],
);
